//! The glyphs of the music font (`assets/fonts/gabc-music.ttf`) with their code points and
//! sizes. Generated by `cargo run -p xtask -- music-font` from Bravura; do not edit.
//!
//! Lengths are in em. One em is four staff spaces, so a staff step is 0.125 em. A glyph's
//! origin is at the height of the staff position it belongs to, at the left of its advance.

/// A glyph of the music font.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum MusicGlyph {
    GClef,
    TimeSig0,
    TimeSig1,
    TimeSig2,
    TimeSig3,
    TimeSig4,
    TimeSig5,
    TimeSig6,
    TimeSig7,
    TimeSig8,
    TimeSig9,
    TimeSigCommon,
    TimeSigCutCommon,
    NoteheadDoubleWhole,
    NoteheadWhole,
    NoteheadHalf,
    NoteheadBlack,
    AugmentationDot,
    Flag8thUp,
    Flag8thDown,
    Flag16thUp,
    Flag16thDown,
    AccidentalFlat,
    AccidentalNatural,
    AccidentalSharp,
    FermataAbove,
    BreathMarkComma,
    RestDoubleWhole,
    RestWhole,
    RestHalf,
    RestQuarter,
    Rest8th,
    Rest16th,
}

/// The size of a glyph, in em.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct MusicMetrics {
    pub advance: f32,
    /// Where the ink starts and ends, from the origin.
    pub left: f32,
    pub right: f32,
    /// How far the ink reaches above and below the origin.
    pub above: f32,
    pub below: f32,
}

impl MusicGlyph {
    /// The character of the glyph in the font: its SMuFL code point.
    pub fn char(self) -> char {
        match self {
            MusicGlyph::GClef => '\u{E050}',
            MusicGlyph::TimeSig0 => '\u{E080}',
            MusicGlyph::TimeSig1 => '\u{E081}',
            MusicGlyph::TimeSig2 => '\u{E082}',
            MusicGlyph::TimeSig3 => '\u{E083}',
            MusicGlyph::TimeSig4 => '\u{E084}',
            MusicGlyph::TimeSig5 => '\u{E085}',
            MusicGlyph::TimeSig6 => '\u{E086}',
            MusicGlyph::TimeSig7 => '\u{E087}',
            MusicGlyph::TimeSig8 => '\u{E088}',
            MusicGlyph::TimeSig9 => '\u{E089}',
            MusicGlyph::TimeSigCommon => '\u{E08A}',
            MusicGlyph::TimeSigCutCommon => '\u{E08B}',
            MusicGlyph::NoteheadDoubleWhole => '\u{E0A0}',
            MusicGlyph::NoteheadWhole => '\u{E0A2}',
            MusicGlyph::NoteheadHalf => '\u{E0A3}',
            MusicGlyph::NoteheadBlack => '\u{E0A4}',
            MusicGlyph::AugmentationDot => '\u{E1E7}',
            MusicGlyph::Flag8thUp => '\u{E240}',
            MusicGlyph::Flag8thDown => '\u{E241}',
            MusicGlyph::Flag16thUp => '\u{E242}',
            MusicGlyph::Flag16thDown => '\u{E243}',
            MusicGlyph::AccidentalFlat => '\u{E260}',
            MusicGlyph::AccidentalNatural => '\u{E261}',
            MusicGlyph::AccidentalSharp => '\u{E262}',
            MusicGlyph::FermataAbove => '\u{E4C0}',
            MusicGlyph::BreathMarkComma => '\u{E4CE}',
            MusicGlyph::RestDoubleWhole => '\u{E4E2}',
            MusicGlyph::RestWhole => '\u{E4E3}',
            MusicGlyph::RestHalf => '\u{E4E4}',
            MusicGlyph::RestQuarter => '\u{E4E5}',
            MusicGlyph::Rest8th => '\u{E4E6}',
            MusicGlyph::Rest16th => '\u{E4E7}',
        }
    }

    pub fn metrics(self) -> MusicMetrics {
        let m = |advance, left, right, above, below| MusicMetrics { advance, left, right, above, below };
        match self {
            MusicGlyph::GClef => m(0.67090, 0.00000, 0.67100, 1.09800, 0.65800),
            MusicGlyph::TimeSig0 => m(0.47021, 0.02000, 0.45000, 0.25100, 0.25000),
            MusicGlyph::TimeSig1 => m(0.33398, 0.02000, 0.31400, 0.25100, 0.25000),
            MusicGlyph::TimeSig2 => m(0.44580, 0.02000, 0.42600, 0.25400, 0.25700),
            MusicGlyph::TimeSig3 => m(0.42090, 0.02000, 0.40100, 0.24900, 0.25100),
            MusicGlyph::TimeSig4 => m(0.47021, 0.02000, 0.45000, 0.25100, 0.25000),
            MusicGlyph::TimeSig5 => m(0.40283, 0.02000, 0.38300, 0.24600, 0.25100),
            MusicGlyph::TimeSig6 => m(0.43408, 0.02000, 0.41400, 0.25100, 0.24900),
            MusicGlyph::TimeSig7 => m(0.44092, 0.02000, 0.42100, 0.24900, 0.25000),
            MusicGlyph::TimeSig8 => m(0.43604, 0.02000, 0.41600, 0.25900, 0.25900),
            MusicGlyph::TimeSig9 => m(0.43408, 0.02000, 0.41400, 0.25100, 0.24900),
            MusicGlyph::TimeSigCommon => m(0.42383, 0.00500, 0.42400, 0.25100, 0.24900),
            MusicGlyph::TimeSigCutCommon => m(0.41699, 0.00000, 0.41800, 0.36100, 0.35900),
            MusicGlyph::NoteheadDoubleWhole => m(0.59912, 0.00000, 0.59900, 0.15500, 0.15500),
            MusicGlyph::NoteheadWhole => m(0.42188, 0.00000, 0.42200, 0.12500, 0.12500),
            MusicGlyph::NoteheadHalf => m(0.29492, 0.00000, 0.29500, 0.12500, 0.12500),
            MusicGlyph::NoteheadBlack => m(0.29492, 0.00000, 0.29500, 0.12500, 0.12500),
            MusicGlyph::AugmentationDot => m(0.10010, 0.00000, 0.10000, 0.05000, 0.05000),
            MusicGlyph::Flag8thUp => m(0.26416, 0.00000, 0.26400, 0.00900, 0.81000),
            MusicGlyph::Flag8thDown => m(0.30615, 0.00000, 0.30600, 0.80800, 0.01400),
            MusicGlyph::Flag16thUp => m(0.27881, 0.00000, 0.27900, 0.00200, 0.81300),
            MusicGlyph::Flag16thDown => m(0.29199, 0.00000, 0.29100, 0.81200, 0.00900),
            MusicGlyph::AccidentalFlat => m(0.22607, 0.00000, 0.22600, 0.43900, 0.17500),
            MusicGlyph::AccidentalNatural => m(0.16797, 0.00000, 0.16800, 0.34100, 0.33500),
            MusicGlyph::AccidentalSharp => m(0.24902, 0.00000, 0.24900, 0.35000, 0.34800),
            MusicGlyph::FermataAbove => m(0.60498, 0.00300, 0.60500, 0.32900, 0.00300),
            MusicGlyph::BreathMarkComma => m(0.15283, 0.00100, 0.15200, 0.25100, -0.00200),
            MusicGlyph::RestDoubleWhole => m(0.12598, 0.00000, 0.12500, 0.25000, -0.00000),
            MusicGlyph::RestWhole => m(0.28320, 0.00000, 0.28200, 0.00900, 0.13500),
            MusicGlyph::RestHalf => m(0.28320, 0.00000, 0.28200, 0.14200, 0.00200),
            MusicGlyph::RestQuarter => m(0.27002, 0.00100, 0.27000, 0.37300, 0.37500),
            MusicGlyph::Rest8th => m(0.25000, 0.00000, 0.24700, 0.17400, 0.25100),
            MusicGlyph::Rest16th => m(0.31982, 0.00000, 0.32000, 0.17900, 0.50000),
        }
    }

    fn anchor(self, which: &str) -> Option<(f32, f32)> {
        match (self, which) {
            (MusicGlyph::NoteheadDoubleWhole, "stem_up") => Some((0.50900, 0.00100)),
            (MusicGlyph::NoteheadDoubleWhole, "stem_down") => Some((0.09000, 0.00100)),
            (MusicGlyph::NoteheadHalf, "stem_up") => Some((0.29500, 0.04200)),
            (MusicGlyph::NoteheadHalf, "stem_down") => Some((0.00000, -0.04200)),
            (MusicGlyph::NoteheadBlack, "stem_up") => Some((0.29500, 0.04200)),
            (MusicGlyph::NoteheadBlack, "stem_down") => Some((0.00000, -0.04200)),
            (MusicGlyph::Flag8thUp, "on_stem_up") => Some((0.00000, -0.01000)),
            (MusicGlyph::Flag8thDown, "on_stem_down") => Some((0.00000, 0.03300)),
            (MusicGlyph::Flag16thUp, "on_stem_up") => Some((0.00000, -0.02200)),
            (MusicGlyph::Flag16thDown, "on_stem_down") => Some((0.00000, 0.03200)),
            _ => None,
        }
    }

    /// Where the lower right corner of a stem that points up meets this note head: to the
    /// right of the origin and above it, in em.
    pub fn stem_up(self) -> Option<(f32, f32)> {
        self.anchor("stem_up")
    }

    /// Where the upper left corner of a stem that points down meets this note head.
    pub fn stem_down(self) -> Option<(f32, f32)> {
        self.anchor("stem_down")
    }

    /// For a flag: where the end of its stem lies, from the flag's origin.
    pub fn on_stem(self) -> Option<(f32, f32)> {
        self.anchor("on_stem_up").or(self.anchor("on_stem_down"))
    }
}

/// The measures of the font's engraving defaults (Bravura 1.482), in em.
pub mod engraving {
    /// The weight of a staff line.
    pub const STAFF_LINE: f32 = 0.03250;
    /// The weight of a stem.
    pub const STEM: f32 = 0.03000;
    /// The weight of a ledger line.
    pub const LEDGER_LINE: f32 = 0.04000;
    /// How far a ledger line reaches beyond the note head, on each side.
    pub const LEDGER_EXTENSION: f32 = 0.10000;
    /// The weight of a bar line.
    pub const THIN_BARLINE: f32 = 0.04000;
    /// The weight of the thick line of a final or repeat bar.
    pub const THICK_BARLINE: f32 = 0.12500;
    /// The room between the two lines of a double bar.
    pub const BARLINE_SEPARATION: f32 = 0.10000;
    /// The room between the thin and the thick line of a final bar.
    pub const THIN_THICK_SEPARATION: f32 = 0.10000;
    /// The room between a repeat bar and its dots.
    pub const REPEAT_DOT_SEPARATION: f32 = 0.04000;
    /// The thickness of a beam.
    pub const BEAM: f32 = 0.12500;
    /// The room between two beams.
    pub const BEAM_SPACING: f32 = 0.06250;
    /// The thickness of a tie or slur at its ends.
    pub const TIE_END: f32 = 0.02500;
    /// The thickness of a tie or slur in its middle.
    pub const TIE_MIDDLE: f32 = 0.05500;
}
